package scheduler

import("context";"errors";"fmt";"sort";"strings";"github.com/eutelic/runnerhub/internal/core";"github.com/eutelic/runnerhub/internal/store")
var ErrNoCapacity=errors.New("no compatible host capacity")
type Decision struct{Host core.Host `json:"host"`;Reason string `json:"reason"`;Used core.Resources `json:"used"`};type Scheduler struct{Store store.Store}
func(s Scheduler)SelectHost(ctx context.Context,pool core.RunnerPool)(Decision,error){hosts,err:=s.Store.ListHosts(ctx);if err!=nil{return Decision{},err};workers,err:=s.Store.ListWorkers(ctx);if err!=nil{return Decision{},err};used:=map[string]core.Resources{};poolActive:=0;for _,w:=range workers{if OccupiesHostResources(w){used[w.HostID]=core.Add(used[w.HostID],w.Resources)};if w.PoolID==pool.ID&&CountsTowardPoolConcurrency(w.State){poolActive++}};if poolActive>=pool.MaxConcurrency{return Decision{},fmt.Errorf("%w: pool concurrency exhausted (%d/%d)",ErrNoCapacity,poolActive,pool.MaxConcurrency)};type candidate struct{h core.Host;used core.Resources;score int64};var candidates []candidate;var rejects []string;for _,h:=range hosts{if reason:=HostRejectionReason(h,pool,used[h.ID]);reason!=""{rejects=append(rejects,h.Name+": "+reason);continue};u:=used[h.ID];score:=(h.Capacity.CPUMillis-u.CPUMillis-pool.Resources.CPUMillis)+(h.Capacity.MemoryBytes-u.MemoryBytes-pool.Resources.MemoryBytes)/(1024*1024);candidates=append(candidates,candidate{h:h,used:u,score:score})};if len(candidates)==0{return Decision{},fmt.Errorf("%w: %s",ErrNoCapacity,strings.Join(rejects,"; "))};sort.SliceStable(candidates,func(i,j int)bool{return candidates[i].score>candidates[j].score});c:=candidates[0];return Decision{Host:c.h,Used:c.used,Reason:"best compatible online host with available requested capacity"},nil}
func CountsTowardPoolConcurrency(s core.WorkerState)bool{switch s{case core.WorkerRequested,core.WorkerProvisioning,core.WorkerStarting,core.WorkerRegistering,core.WorkerReady,core.WorkerBusy:return true;default:return false}}
func OccupiesHostResources(w core.Worker)bool{switch w.State{case core.WorkerDeleted:return false;case core.WorkerFailed,core.WorkerCompleted,core.WorkerCleanupPending,core.WorkerDeleting:return strings.TrimSpace(w.ProviderHandle)!="";default:return true}}
func HostRejectionReason(h core.Host,pool core.RunnerPool,used core.Resources)string{if h.State!=core.HostOnline{return "not online"};if !matchTags(h.Tags,pool.HostSelector){return "selector mismatch"};if !supportsIsolation(h,pool.Isolation){return "isolation unsupported"};if reason:=resourceExhaustionReason(h.Capacity,used,pool.Resources);reason!=""{return reason};return ""}
func resourceExhaustionReason(cap,used,req core.Resources)string{var reasons []string;if available:=cap.CPUMillis-used.CPUMillis;available<req.CPUMillis{reasons=append(reasons,fmt.Sprintf("cpu exhausted (available=%dm requested=%dm)",available,req.CPUMillis))};if available:=cap.MemoryBytes-used.MemoryBytes;available<req.MemoryBytes{reasons=append(reasons,fmt.Sprintf("memory exhausted (available=%d requested=%d)",available,req.MemoryBytes))};if available:=cap.DiskBytes-used.DiskBytes;available<req.DiskBytes{reasons=append(reasons,fmt.Sprintf("disk exhausted (available=%d requested=%d)",available,req.DiskBytes))};if available:=cap.GPUs-used.GPUs;available<req.GPUs{reasons=append(reasons,fmt.Sprintf("gpu exhausted (available=%d requested=%d)",available,req.GPUs))};return strings.Join(reasons,", ")}
func matchTags(tags,sel map[string]string)bool{for k,v:=range sel{if tags[k]!=v{return false}};return true}
func supportsIsolation(h core.Host,mode core.IsolationMode)bool{if h.Tags==nil{return mode==core.IsolationContainerTrusted&&h.Provider=="docker"};key:="isolation."+string(mode);if v,ok:=h.Tags[key];ok{return v=="true"};return mode==core.IsolationContainerTrusted&&h.Provider=="docker"}
